    // this.login();
    eval(String(source.loginUrl));
    login.call(this);
  }
  let url = this._URL(path, searchParams);
  return url
}

function _URL(path, searchParams, isLogin) {
  const {
    java
  } = this;
  let params = ["app_signature_md5", "app_version", "channel"];
  if (typeof searchParams !== 'object') searchParams = {};
  if (!isLogin) {
    params = ["app_signature_md5", "app_version", "channel", "account", "login_token"];
    let data = this.getData();
    config.login_token = data["login_token"];
    config.account = data["account"];
  }

  for (let paramkey of params) {
    if (config[paramkey]) searchParams[paramkey] = config[paramkey];
  }
  let body = `secret_content=${this.encrypt(searchParams)}`
  return `${config.BASEURL}${path},${JSON.stringify({ method: "POST", body: body, headers: { "User-Agent": config.UserAgent } })}`
}

function encrypt(decrypted) {
  const {
    java
  } = this;
  let aesKey = java.hexDecodeToByteArray(java.digestHex(secretKey, "SHA-256"));
  let iv = java.hexDecodeToByteArray("0".repeat(32));
  let aesDecipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", aesKey, iv);
  decrypted = JSON.stringify(decrypted);
  let encrypted = aesDecipher.encryptBase64(decrypted);
  return encrypted
}

function decrypt(encrypted, key) {
  const {
    java
  } = this;
  let aesKey = java.hexDecodeToByteArray(java.digestHex(key || secretKey, "SHA-256"));
  let iv = java.hexDecodeToByteArray("0".repeat(32));
  let aesDecipher = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", aesKey, iv);
  let decrypted = aesDecipher.decryptStr(encrypted);
  try {
    decrypted = JSON.parse(decrypted);
    if (decrypted.code != "100000") {
      java.toast(decrypted.tip);
    }
  } catch (error) { }
  return decrypted
}
